@'
import fs from 'node:fs';
const data=JSON.parse(fs.readFileSync('.dip-local/model-controlled-v4.json'));
for(const pair of data.pairs) {
 const arm=pair.arms.with;
 for(const phase of ['seed','recovery']) {
  const t=arm[phase];
  console.log(JSON.stringify({pair:pair.index,phase,completed:t.completed,timeout:t.timedOut,errors:t.mcpErrors,items:t.itemCounts,final:t.final?.slice(0,1500)}));
 }
}
'@ | node --input-type=module
